style.css:
@-moz-document domain("roblox.com") {
/* ── COLORS ── */
:root {
    --marsey-orange: #ff9b42;
    --marsey-red: #e85b4a;
    --marsey-cream: #fff1d8;
    --marsey-pink: #ffc6c6;
    --marsey-brown: #713d2c;
    --marsey-dark: #321e1a;
}

/* ── FULL MARSEY WALLPAPER ── */
html,
body,
body.rbx-body {
    background-color: var(--marsey-cream) !important;
    background-image:
        linear-gradient(
            rgba(255, 241, 216, 0.12),
            rgba(255, 241, 216, 0.12)
        ),
        url("https://i.ibb.co/KcyMn9SV/IMG-9991.jpg") !important;
    background-repeat: no-repeat !important;
    background-position: center center !important;
    background-size: cover !important;
    background-attachment: fixed !important;
}

/* ── MAKE ROBLOX PAGE BACKGROUNDS TRANSPARENT ── */
#container-main,
#content,
.container-main,
.main-container,
.home-container,
.profile-container,
.game-details-container,
.rbx-body,
.content {
    background-color: transparent !important;
    background-image: none !important;
}

/* ── NAVIGATION BAR ── */
.navbar,
.navbar-default,
.rbx-navbar {
    background: var(--marsey-orange) !important;
    border-color: var(--marsey-red) !important;
}

.navbar a,
.rbx-navbar a {
    color: var(--marsey-dark) !important;
}

/* ── GAME CARDS ── */
.game-card,
.game-card-container,
.avatar-card-container {
    background: rgba(255, 248, 235, 0.92) !important;
    border: 2px solid var(--marsey-pink) !important;
    border-radius: 16px !important;
    box-shadow: 0 4px 10px rgba(113, 61, 44, 0.15) !important;
}

/* ── BUTTONS ── */
button,
.btn-primary,
.btn-common-play-game-lg {
    background: var(--marsey-red) !important;
    color: white !important;
    border: 2px solid var(--marsey-orange) !important;
    border-radius: 12px !important;
}

/* ── SEARCH AND INPUTS ── */
input,
.form-control {
    background: var(--marsey-cream) !important;
    color: var(--marsey-brown) !important;
    border: 2px solid var(--marsey-pink) !important;
    border-radius: 12px !important;
}

/* ── TEXT ── */
h1,
h2,
h3,
h4,
.text-name,
.game-name {
    color: var(--marsey-brown) !important;
}

/* ── LINKS ── */
a {
    color: var(--marsey-red) !important;
}

a:hover {
    color: var(--marsey-orange) !important;
}

/* ── SCROLLBAR ── */
::-webkit-scrollbar {
    width: 10px !important;
}

::-webkit-scrollbar-track {
    background: var(--marsey-cream) !important;
}

::-webkit-scrollbar-thumb {
    background: var(--marsey-orange) !important;
    border-radius: 10px !important;
}
}
